   [
    "Setup",
    "Mark a square with four cones; each quarter of the square is a receiving space. The receiver starts in the middle and the server stands just outside the square with a supply of balls."
   ],
   [
    "Instructions",
    "The receiver keeps moving and scanning between the spaces. When they show a good angle in an open space, the server passes into that space. The receiver controls the ball, returns the pass and immediately moves again to a new space. Work for 45–60 seconds, then swap roles."
   ],
   [
    "Coaching points",
    "Move and scan; show a good angle for the server; receive in space; control and return; move again to a new space; key cue: move, show, receive, move again."
   ],
   [
    "Work-to-rest guidance",
    "45–60 seconds as the receiver, then swap; complete 3–4 turns each."
   ],
   [
    "Progression",
    "Add a defender who tracks the receiver while the server still passes to the open space; limit the receiver to two touches; the server moves along the side of the square; the receiver turns and dribbles out through a side of the square."
   ],
   [
    "Regression",
    "Remove the defender, make the square bigger, let the server call the space or allow the receiver to stop the ball before returning it."
   ],
   [
    "Inclusive adaptation",
    "Use coloured cones so the server can call a colour, let players move at their own pace and allow extra touches."
   ],
   [
    "Safety",
    "Leave space between squares, keep spare balls beside the server and not inside the square, and avoid contact when a defender is added."
   ]
