   [
    "Setup",
    "Create a 5 metre “swamp” between two lines. Partners stand on opposite sides of the swamp with one ball between them."
   ],
   [
    "Instructions",
    "Pairs have to pass over the swamp without the ball touching it. Once everyone succeeds, make the swamp 6 metres, then 8, 10 and 12 metres. Then turn it into a game: how wide can your swamp get?"
   ],
   [
    "Coaching points",
    "Coach the actual technique rather than encouraging players simply to kick harder: plant foot beside the ball, pointing towards the target; ankle locked; strike through the middle of the ball; follow through towards the target. For driven passes, encourage laces or inside-laces through the middle of the ball rather than toe-poking underneath it. Aim for accuracy as the distance increases."
   ],
   [
    "Work-to-rest guidance",
    "Continuous low-intensity passing; change the distance every 2–3 minutes and take a short break at each change."
   ],
   [
    "Progression",
    "Widen the swamp to 6, 8, 10 and 12 metres; use the weaker foot; allow only two touches (control, then pass); keep score as a pair."
   ],
   [
    "Regression",
    "Keep the swamp at 5 metres or make it narrower, allow the ball to bounce once in the swamp or use a lighter ball."
   ],
   [
    "Inclusive adaptation",
    "Let each pair choose their own swamp width, use a lighter or smaller ball and count personal bests rather than comparing pairs."
   ],
   [
    "Safety",
    "Set pairs side by side so that all passes travel in the same direction, leave space between channels, receive the ball with the feet (no heading) and warn others before fetching a stray ball."
   ]
