   [
    "Setup",
    "Split the pitch into three vertical channels running from goal to goal. Play a normal match."
   ],
   [
    "Instructions",
    "Play a normal match, but award 2 points for a goal following a switch from one outside channel to the other. At first you’ll probably have to repeatedly ask: “Where’s the space?” Eventually one of the players will look across and realise there’s a teammate standing completely free on the opposite side. That’s the moment you’re looking for."
   ],
   [
    "Coaching points",
    "Switch outside to outside: move the ball quickly and accurately. Look across the pitch: scan, see space, play early. Players on the far side stay wide so the switch is on."
   ],
   [
    "Work-to-rest guidance",
    "Games of 4–5 minutes with 90 seconds to recover; play 2–3 games."
   ],
   [
    "Progression",
    "The switch must be made in three passes or fewer, a direct switch in one pass earns a bonus point, or add the rule that nobody can pass back to the player who just passed to them."
   ],
   [
    "Regression",
    "Count the 2 points even if the switch goes through the central channel in two passes, or add a neutral wide player on each side."
   ],
   [
    "Inclusive adaptation",
    "Balance teams carefully, use flat markers for the channel lines and praise every attempt to look across the pitch, not just successful switches."
   ],
   [
    "Safety",
    "Use flat markers for the channel lines so players do not trip; no sliding tackles; check that goals are secure."
   ]
