    "Throw the ball so it bounces awkwardly in front of the defender. They have to decide how to deal with it without heading. Start with no pressure. Give points for: controlling it and passing back = 3; a controlled clearance into the wide gate = 2; getting their body behind it and keeping it safe = 1. Reset and repeat, changing the type of bounce regularly."
