   [
    "Setup",
    "Two defenders start inside the area in front of the goal. Two attackers start outside the area. The coach stands beyond them with a supply of balls."
   ],
   [
    "Instructions",
    "Two defenders play against two attackers towards a goal. Instead of starting with a pass, throw, roll or bounce the ball unpredictably into the defensive area. Then everyone plays normally: the attackers try to score and the defenders try to win the ball and clear. Sometimes give the defenders time; sometimes put them immediately under pressure."
   ],
   [
    "Coaching points",
    "This forces a genuine decision rather than rehearsing one predetermined technique. Read the bounce: adjust early to the flight, spin and second ball. Communicate: call and organise early and clearly. Make a real decision: control, pass, shoot or clear, with no hesitation. Play on: as soon as the ball is live, all players are in the game."
   ],
   [
    "Work-to-rest guidance",
    "Goes of 10–20 seconds with 45–60 seconds to recover; rotate the fours after 3–4 goes."
   ],
   [
    "Progression",
    "Let the defenders score by playing out through wide gates, play 3v3 or serve from different positions."
   ],
   [
    "Regression",
    "Give the defenders more time on every serve, or play 2v1."
   ],
   [
    "Inclusive adaptation",
    "Balance the pairs carefully, use a softer ball and vary how much time each pair of defenders is given."
   ],
   [
    "Safety",
    "No heading; serve below head height and into space, never at a player; no sliding tackles; check that the goal is secure."
   ]
