// Notes that introduce a section of the repository.
window.SECTION_NOTES = {
 "Big Pitch": [
  "A rule to use often in 5v5 and 7v7 training games: nobody can pass back to the player who just passed to them. The receiver has to find somebody else, and the passer has to move somewhere useful. It breaks the common pattern of pass, stand still, get it back, with everyone gathering around the ball."
 ],
 "Positioning": [
  "Freeze frames: in any of these games, shout “Freeze!” and ask everyone to stand still for about ten seconds. Ask one or two quick questions – Who has the ball? Who is helping in front? Who is helping beside? Who is protecting behind? Where is our biggest space? – let the players fix the picture themselves, then restart straight away. It is a snapshot, not a lecture.",
  "Four calls to use in every positioning game: BIG! – we’ve got the ball, spread out. SMALL! – they’ve got it, get together. SHOW! – move somewhere the player on the ball can see you. COVER! – a teammate has gone to the ball, protect the space behind them."
 ],
 "Look, Receive, Play": [
  "Four short coaching cues for midfielders: SCAN – look before the ball comes. OPEN – body side-on so you can see more of the pitch. FIRST TOUCH – take it towards where you want to play. GO AGAIN – pass and immediately find another space.",
  "Don’t teach “look up” only after the ball has been controlled – that is often too late for a central midfielder. The habit to build is: look → ball travels → look again → receive → decide and play."
 ],
 "20-Minute Matches": [
  "Each of these is a 20-minute match to finish a session. One simple condition rewards the behaviour worked on earlier, and the game itself does most of the coaching: keep instructions short and let play flow.",
  "For the last 5–7 minutes of almost any of these games, switch to “Coach Goes Quiet”: remove the bonus points and conditions, say very little, and count how often the session’s behaviour appears without a reward."
 ],
 "Practice to Match": [
  "Each entry pairs a short practice with a condition for the 7v7 match that follows, so the players meet the same football problem twice: first in a small group, then in the game. Keep the match bonus modest – it should encourage the behaviour without taking over the game.",
  "Rather than adding completely new drills every week, repeat these core practices with increasing difficulty. One possible order: Four-Gate Escape, Pressure Compass, Escape the Press, Wide & Arrive, Protect the House, The Safety Player, Information Football with a silent-coach match, then Scenario Football. Meanwhile, both feet, scanning and decision-making become permanent coaching threads rather than standalone sessions."
 ],
 "Agility Ladder": [
  "The ladder isn’t the main event. Its job is to create a little physical and mental load immediately before a football action – a look, a first touch, a pass or a finish – so keep the ladder patterns simple and the football action sharp."
 ]
};

